import React from "react";
import withNavigation from "../utils/withNavigation";
import axiosInstance from "../configurations/instance";

class Verification extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      code: "",
      error: "",
    };
  }

  handleSubmit = () => {
    const { code } = this.state;
    const email = localStorage.getItem("email");

    axiosInstance
      .post("/checker/confirm-checker", { email, code })
      .then((response) => {
        console.log("Verification successful", response.data);

        // Устанавливаем токены в localStorage и cookies
        localStorage.setItem("token", response.data.accessToken);

        this.props.navigate("/checker-events");
      })
      .catch((error) => {
        console.error("Verification failed", error.response?.data?.message || error.message);
        this.setState({ error: "Неверный код подтверждения. Попробуйте снова." });
      });
  };

  render() {
    const { error } = this.state;

    return (
      <div className="verification-container">
        <h1>Введите 6-значный код</h1>
        <p>На вашу почту был отправлен код</p>
        {error && <p className="error-message">{error}</p>}
        <div className="form-group">
          <h3 htmlFor="verificationCode">Код</h3>
          <input
            id="verificationCode"
            type="text"
            minLength="6"
            maxLength="6"
            onChange={(e) => this.setState({ code: e.target.value })}
            placeholder="Введите код"
          />
        </div>

        <button type="button" onClick={this.handleSubmit}>
          Подтвердить
        </button>
      </div>
    );
  }
}

export default withNavigation(Verification);
